"content": "import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    original_to_final = {}
    current_to_original = {}
    for i in range(1, n+1):
        old, new = data[i].split()
        if old in current_to_original:
            orig = current_to_original[old]
            # update mapping
            original_to_final[orig] = new
            del current_to_original[old]
            current_to_original[new] = orig
        else:
            # new original user
            orig = old
            original_to_final[orig] = new
            current_to_original[new] = orig
    # Prepare output
    pairs = [(orig, original_to_final[orig]) for orig in original_to_final]
    pairs.sort(key=lambda x: x[1])
    print(len(pairs))
    for orig, final in pairs:
        print(orig, final)

if __name__ == "__main__":
    main()
"
}

