"content": "import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    # Mapping from current handle to original handle
    cur_to_orig = {}
    # Mapping from original handle to its current handle (for ordering)
    orig_to_cur = {}
    # Order of original handles as they appear
    order = []
    for i in range(1, n + 1):
        old, new = data[i].split()
        if old in cur_to_orig:
            original = cur_to_orig[old]
            del cur_to_orig[old]
        else:
            original = old
            order.append(original)
        cur_to_orig[new] = original
        orig_to_cur[original] = new
    print(len(orig_to_cur))
    for original in order:
        if original in orig_to_cur:
            print(original, orig_to_cur[original])

if __name__ == "__main__":
    solve()
"
}

