"content": "import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    forward = {}
    used_as_new = set()
    for _ in range(n):
        old = next(it)
        new = next(it)
        forward[old] = new
        used_as_new.add(new)
    originals = [handle for handle in forward.keys() if handle not in used_as_new]
    originals.sort()
    result = []
    for o in originals:
        cur = o
        while cur in forward:
            cur = forward[cur]
        result.append((o, cur))
    out_lines = []
    out_lines.append(str(len(result)))
    for o, f in result:
        out_lines.append(f"{o} {f}")
    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    main()
"
}

