    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    cur_to_orig = {}
    final = {}
    for i in range(1, n+1):
        old, new = data[i].split()
        orig = cur_to_orig.get(old, old)
        # update mapping: original's final handle becomes new
        final[orig] = new
        # remove old from cur_to_orig (if present)
        if old in cur_to_orig:
            del cur_to_orig[old]
        # map new to original
        cur_to_orig[new] = orig
    # output
    keys = sorted(final.keys())
    out = []
    out.append(str(len(keys)))
    for k in keys:
        out.append(f"{k} {final[k]}")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
