"content": "import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    cur_to_orig = {}
    orig_to_cur = {}
    for i in range(1, n+1):
        old, new = data[i].split()
        # Find original handle for this user
        orig = cur_to_orig.get(old, old)
        # Update mappings
        cur_to_orig[new] = orig
        if old in cur_to_orig:
            del cur_to_orig[old]
        orig_to_cur[orig] = new
    # Output
    items = sorted(orig_to_cur.items())
    print(len(items))
    for orig, final in items:
        print(orig, final)

if __name__ == "__main__":
    main()
