    n, k = map(int, data[:2])
    # dp[a][i] = answer for i planes and age a
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for i in range(n + 1):
        dp[1][i] = 1
    for a in range(2, k + 1):
        # prefix sums of dp[a-1]
        prefix = [0] * (n + 1)
        prefix[0] = dp[a - 1][0]
        for i in range(1, n + 1):
            prefix[i] = (prefix[i - 1] + dp[a - 1][i]) % MOD
        dp[a][0] = 1
        for i in range(1, n + 1):
            dp[a][i] = (1 + prefix[i - 1]) % MOD
    print(dp[k][n] % MOD)

